static int
compare_int(const void *a, const void *b)
{
    return (*(const int *)a) - (*(const int *)b);
}

static void
draw_fillpoly(SDL_Surface *dst, int *vx, int *vy, int n, Uint32 color)
{
    int i, j, y;
    int miny, maxy;
    int x1, y1;
    int x2, y2;
    int ints;
    int *polyints = PyMem_New(int, n);
    if (polyints == NULL) {
        PyErr_NoMemory();
        return;
    }

    /* Determine Y maxima */
    miny = vy[0];
    maxy = vy[0];
    for (i = 1; (i < n); i++) {
        miny = MIN(miny, vy[i]);
        maxy = MAX(maxy, vy[i]);
    }

    if (miny == maxy) {
        /* Special case: polygon only 1 pixel high. */
        int minx, maxx;

        /* Determine X bounds */
        minx = vx[0];
        maxx = vx[0];
        for (j = 1; (j < n); j++) {
            minx = MIN(minx, vx[j]);
            maxx = MAX(maxx, vx[j]);
        }
        drawhorzlineclip(dst, color, minx, miny, maxx);
        PyMem_Free(polyints);
        return;
    }

    /* Draw, scanning y */
    for (y = miny; (y <= maxy); y++) {
        ints = 0;
        for (i = 0; (i < n); i++) {
            if (!i) {
                j = n - 1;
            }
            else {
                j = i - 1;
            }
            y1 = vy[j];
            y2 = vy[i];
            if (y1 < y2) {
                x1 = vx[j];
                x2 = vx[i];
            }
            else if (y1 > y2) {
                y2 = vy[j];
                y1 = vy[i];
                x2 = vx[j];
                x1 = vx[i];
            }
            else {
                continue;
            }
            if ( ((y >= y1) && (y < y2)) ||
                  ((y == maxy) && (y <= y2)) ) {
                polyints[ints++] = (y - y1) * (x2 - x1) / (y2 - y1) + x1;
            }
        }
        qsort(polyints, ints, sizeof(int), compare_int);

        for (i = 0; (i < ints); i += 2) {
            drawhorzlineclip(dst, color, polyints[i], y, polyints[i + 1]);
        }
    }
    PyMem_Free(polyints);
}

