SQUARE = [[0,0],[3,0],[3,3],[0,3]]
DIAMOND = [(1,3),(3,5),(5,3),(3,1)]
CROSS = ([2, 0], [4, 0], [4, 2], [6, 2],
         [6, 4], [4, 4], [4, 6], [2, 6],
         [2, 4], [0, 4], [0, 2], [2, 2])

def fill(poly, combiner):
    n = len(poly)
    vx = [p[0] for p in poly]
    vy = [p[1] for p in poly]
    miny, maxy = min(vy), max(vy)
    rows = {}
    for y in range(miny, maxy+1):
        ints_start = []
        ints_end = []
        for i in range(n):
            j = n-1 if i==0 else i-1
            y1, y2 = vy[j], vy[i]
            if y1 < y2:
                x1, x2 = vx[j], vx[i]
            elif y1 > y2:
                y2, y1 = vy[j], vy[i]
                x2, x1 = vx[j], vx[i]
            else:
                continue
            if (y1 <= y < y2) or (y == maxy and y <= y2):
                ints_start.append((y - y1) * (x2 - x1) // (y2 - y1) + x1)
            if (y1 < y <= y2) or (y == miny and y >= y1):
                ints_end.append((y - y1) * (x2 - x1) // (y2 - y1) + x1)
        # build boolean x membership sets and union them
        minx, maxx = min(vx), max(vx)
        filled = set()
        ints_start.sort()
        for i in range(0, len(ints_start), 2):
            if i+1 < len(ints_start):
                for x in range(ints_start[i], ints_start[i+1]+1):
                    filled.add(x)
        ints_end.sort()
        for i in range(0, len(ints_end), 2):
            if i+1 < len(ints_end):
                for x in range(ints_end[i], ints_end[i+1]+1):
                    filled.add(x)
        rows[y] = sorted(filled)
    return rows, minx, maxx

def print_rows(rows, minx, maxx, label):
    print(label)
    for y in sorted(rows):
        cells = rows[y]
        line = [' ']* (maxx-minx+1)
        for x in cells:
            if minx <= x <= maxx:
                line[x-minx] = '#'
        print(f"{y:2d}: " + ''.join(line))

r, minx, maxx = fill(SQUARE, None)
print_rows(r, minx, maxx, "square union")
print("square membership 0..3 x 0..3 all filled:", all(all(x in r[y] for x in range(4)) for y in range(4)))
print()
r, minx, maxx = fill(DIAMOND, None)
print_rows(r, minx, maxx, "diamond union")
# diamond expectation: corners (1,3),(3,5),(5,3),(3,1) and inner 2..4,2..4
diam = set()
for x,y in DIAMOND: diam.add((x,y))
for x in range(2,5):
    for y in range(2,5):
        diam.add((x,y))
ok = all((x,y) in r[y] for (x,y) in diam)
